#!/usr/bin/env python3
"""Regenerate docs/RESULTS_INDEX.md from results/ run directories."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RESULTS = ROOT / "results"
OUT = ROOT / "docs" / "RESULTS_INDEX.md"


def load_json(path: Path):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


def main() -> int:
    lines = [
        "# Results index",
        "",
        "Generated by `scripts/update_results_index.py`. Failed and incomplete runs",
        "are retained: do not delete a run directory because its result was bad.",
        "",
        "| Run directory | Status | Exit | Model | Backend | Reader | Artefacts |",
        "|---|---|---:|---|---|---|---|",
    ]
    runs = sorted([p for p in RESULTS.iterdir() if p.is_dir()], key=lambda p: p.name) if RESULTS.exists() else []
    if not runs:
        lines.append("| _none_ | no recorded runs in this checkout | | | | | |")
        lines += ["", "Generated `results/` directories are ignored by Git. Create them with",
                  "`scripts/run_record.sh configs/example.env` or `scripts/phase0_exit.sh`;",
                  "then re-run this script to index them."]
    for run in runs:
        stdout = load_json(run / "stdout.json") or {}
        exit_file = run / "exit_code.txt"
        exit_code = exit_file.read_text().strip() if exit_file.exists() else ""
        status = stdout.get("status", "incomplete")
        report = run / "report.json"
        metrics = run / "metrics.json"
        trace = run / "trace.jsonl"
        artefacts = " ".join(f"`{p.name}`" for p in (report, metrics, trace) if p.exists()) or "_none_"
        lines.append(
            f"| `{run.relative_to(ROOT).as_posix()}` | {status} | {exit_code or '?'} | "
            f"{stdout.get('model', '')} | {stdout.get('backend', '')} | "
            f"{stdout.get('reader', '')} | {artefacts} |"
        )
    lines += [
        "",
        "All generated run data is ignored by Git. Archive a run deliberately by",
        "copying its directory and hashes into a release artefact if it must persist.",
        "",
    ]
    OUT.write_text("\n".join(lines), encoding="utf-8")
    print(json.dumps({"status": "pass", "run_directories": len(runs), "output": OUT.relative_to(ROOT).as_posix()}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
